 const statusHTML=status?`<span class="gateway-open-state ${status.open?'is-open':'is-closed'}" data-gateway-status="${esc(b.id)}">${icon('clock',14)} ${esc(status.label)}</span>`:'';
 const branding=brandingForBranch(b);
