 return `<article class="branch-card branch-v4" data-branch-url="/tienda/${encodeURIComponent(b.id)}" style="--branch:${esc(border)};--delay:${i*70}ms"><div class="branch-v4-photo">${branchPhoto(b,i)}</div><div class="branch-v4-info"><div class="branch-v4-heading"><div><span class="branch-v4-overline">${esc(branding.overline)}</span><h3>${esc(b.name)}</h3></div><img class="lf32-card-logo" src="${esc(logo)}" alt="Logo de ${esc(b.name)}" loading="lazy"></div>${statusHTML}<div class="branch-v4-facts"><div>${icon('pin',16)}<span>${addressText}</span></div><div>${icon('clock',16)}<span>${hoursText}</span></div><div>${icon('phone',16)}<span>${esc(phone)}</span></div></div><div class="gateway-card-actions"><div class="gateway-card-actions-secondary">${mapLink?`<a class="gateway-card-mini" href="${esc(mapLink)}" target="_blank" rel="noopener noreferrer">${icon('pin',15)} Cómo llegar</a>`:''}<a class="gateway-card-mini" href="${whatsapp}" target="_blank" rel="noopener noreferrer">${icon('phone',15)} WhatsApp</a></div><a data-nav class="branch-enter" href="/tienda/${encodeURIComponent(b.id)}">Ver productos ${icon('arrow',18)}</a></div></div></article>`;
