function seasonalProducts(){return app.shop.products.filter(p=>/navidad|arbol|árbol|adorno|luces|guirnalda|nacimiento|disfraz|halloween|decoracion|decoración|regalo|fiestas patrias|temporada|especial/i.test([p.name,p.subCategory,p.description,p.categoryId].join(' ')));}
function seasonalPage(){const products=seasonalProducts();return `<main>${pageBanner('PRODUCTOS ESPECIALES','Ideas para cada <em>temporada.</em>','Encuentra regalos, decoración y productos de temporada disponibles en esta sucursal.','purple')}<section class="wrap section">${sectionTitle('CATEGORÍA ESPECIAL','Productos de <em>temporada.</em>')}${listingMarkup(products,`<div class="search-empty"><h3>Próximamente, nuevas colecciones.</h3><p>Cuando publiquemos artículos especiales en esta sucursal aparecerán aquí.</p></div>`)}</section></main>`;}
