async function loadPrintRates(){try{const data=await api('/api/public/rates/'+encodeURIComponent(app.branchId));if(app.branchId!==data.branchId)return;app.printRates=data.rates;const strip=$('#print-rate-strip');if(strip){const names=[['Fotocopia B/N','copyBW','cara'],['Impresión B/N','printBW','cara'],['Copia a color','copyColor','cara base'],['Impresión a color','printColor','cara base'],['Escaneo','scanPage','página']];strip.innerHTML=names.map(([label,k,unit])=>`<span>${label} <b>${Number(data.rates[k])>0?money(data.rates[k]):'Por configurar'} / ${unit}</b></span>`).join('');}}catch(e){console.warn('Tarifas no disponibles',e);}}
function printQuotePage(){const r=app.printRates||{};const price=(n)=>Number(n)>0?money(n):'Por configurar';return `<main>${pageBanner('COPIAS, IMPRESIONES Y ESCANEOS','Calcula el costo de <em>tu trabajo.</em>','Selecciona cómo quieres preparar tus documentos y conoce las tarifas de esta sucursal.','blue')}<div class="wrap section print-page"><div class="panel-print"><h2>Calculadora de copias, impresiones y escaneos</h2><p>Precios de ${esc(app.shop.branch.name)}, editables desde el administrador.</p><div class="print-rate-strip" id="print-rate-strip"><span>Fotocopia B/N <b>${price(r.copyBW??.15)} / cara</b></span><span>Impresión B/N <b>${price(r.printBW??.20)} / cara</b></span><span>Copia a color <b>${price(r.copyColor)} / cara base</b></span><span>Impresión a color <b>${price(r.printColor)} / cara base</b></span><span>Escaneo <b>${price(r.scanPage)} / página</b></span></div><form id="print-quote-form" class="print-form"><label>Servicio<select name="kind" id="print-service-kind"><option value="copy">Fotocopias</option><option value="print">Impresiones</option><option value="scan">Escaneo de documentos</option></select></label><label data-print-only>Tipo de tinta<select name="color" id="print-color-mode"><option value="bw">Blanco y negro</option><option value="color">A color</option><option value="mixed">Mixto: páginas B/N y a color</option></select></label><label class="print-mixed-slider" data-print-only data-mixed-only hidden><span>Porcentaje de páginas a color: <strong id="mixed-color-display">30 %</strong></span><input name="colorPercent" type="range" min="0" max="100" step="1" value="30" aria-label="Porcentaje de páginas a color"><span id="mixed-bw-display">70 % en blanco y negro</span><small>Estimación manual según las páginas del documento.</small></label><label><span id="print-pages-label">Páginas del documento</span><input name="pages" type="number" min="1" max="5000" value="20" required></label><label data-print-only>Copias de cada página<input name="copies" type="number" min="1" max="1000" value="1" required></label><label data-print-only>Cantidad de color<select name="coverage"><option value="low">Poco color</option><option value="medium">Color moderado</option><option value="high">Mucho color / fotografía</option></select></label><label class="print-check" data-print-only><input type="checkbox" name="duplex"> Doble cara</label><label data-scan-only hidden>Formato de entrega<select name="scanFormat"><option value="pdf">Documento PDF</option><option value="jpg">Imágenes JPG</option></select></label><label data-print-only>Imagen de referencia (opcional)<input type="file" name="reference" id="print-color-reference" accept="image/png,image/jpeg,image/webp"><small id="print-color-analysis">Adjunta una imagen para estimar la cantidad de color.</small></label><p class="print-scan-note" data-scan-only hidden>Trae las hojas físicas a la sucursal. El escaneo se cobra por página y se entrega en PDF o JPG.</p><button class="button primary" type="submit">Calcular importe ${icon('arrow',17)}</button></form><div class="print-result" id="print-result" aria-live="polite">Completa los datos y calcula tu importe.</div><small>Los trabajos especiales pueden necesitar revisión por la tienda.</small></div></div></main>`;}
function syncPrintService(){
 const form=$('#print-quote-form');if(!form)return;
 const scanning=form.querySelector('[name=kind]')?.value==='scan';
 form.querySelectorAll('[data-print-only]').forEach(node=>{node.hidden=scanning;node.querySelectorAll('input,select').forEach(control=>control.disabled=scanning);});
 form.querySelectorAll('[data-scan-only]').forEach(node=>{node.hidden=!scanning;node.querySelectorAll('input,select').forEach(control=>control.disabled=!scanning);});
 syncPrintColorMode();
 const label=$('#print-pages-label');if(label)label.textContent=scanning?'Páginas que necesitas escanear':'Páginas del documento';
 const result=$('#print-result');if(result)result.textContent='Completa los datos y calcula tu importe.';
}
function syncPrintColorMode(){const form=$('#print-quote-form');if(!form)return;const isMixed=form.querySelector('[name=color]')?.value==='mixed'&&form.querySelector('[name=kind]')?.value!=='scan';const block=form.querySelector('[data-mixed-only]');if(block){block.hidden=!isMixed;block.querySelector('input').disabled=!isMixed;}const slider=form.querySelector('[name=colorPercent]');if(slider){const n=Number(slider.value);const color=$('#mixed-color-display');if(color)color.textContent=n+' %';const bw=$('#mixed-bw-display');if(bw)bw.textContent=(100-n)+' % en blanco y negro';}}
function storefront(){const products=app.shop.products.filter(p=>p.price>0);const selected={beneficios:()=>`<section class="wrap section service-overview">${sectionTitle('TE LO PONEMOS FÁCIL','Más soluciones, <em>menos complicaciones.</em>')}<div class="service-overview-grid"><a data-nav href="${urlBranch('/impresiones')}">${icon('printer',24)}<b>Copias e impresiones</b><small>Calcula tus hojas, tinta y acabados</small><span>Calcular →</span></a><a data-nav href="${urlBranch('/categoria/cuadernos')}">${icon('book',24)}<b>Útiles escolares</b><small>Encuentra artículos por categoría</small><span>Explorar →</span></a><a data-nav href="${urlBranch('/categoria/arte')}">${icon('palette',24)}<b>Arte y creatividad</b><small>Colores, pinturas y materiales</small><span>Explorar →</span></a><a data-nav href="${urlBranch('/campanas')}">${icon('gift',24)}<b>Campañas especiales</b><small>Navidad, escolar, Día de la Madre y más</small><span>Ver campañas →</span></a></div></section>`,categorias:()=>`<section class="wrap section">${sectionTitle('EXPLORA A TU MANERA','¿Qué necesitas <em>hoy?</em>','Encuentra rápido el tipo de artículo que estás buscando.',`<a class="text-link" data-nav href="${urlBranch('/catalogo')}">Ver todos ${icon('arrow',17)}</a>`)}${categoryTiles()}</section>`,destacados:()=>`<section class="wrap section">${sectionTitle('NUESTROS FAVORITOS','Los más buscados <em>por aquí.</em>','Una selección para empezar.',`<a class="text-link" data-nav href="${urlBranch('/catalogo')}">Ir al catálogo ${icon('arrow',17)}</a>`)}${cards(products.filter(p=>p.featured).slice(0,8).length?products.filter(p=>p.featured).slice(0,8):products.slice(0,8),'carousel')}</section>`,novedades:()=>`<section class="wrap section">${sectionTitle('RECIÉN LLEGADOS','Un poquito de <em>novedad.</em>','Ideas nuevas para tu día a día.',`<a class="text-link" data-nav href="${urlBranch('/novedades')}">Ver novedades ${icon('arrow',17)}</a>`)}${cards(products.filter(p=>p.isNew).slice(0,4).length?products.filter(p=>p.isNew).slice(0,4):products.slice(8,12),'carousel')}</section>`,catalogo:()=>`<section class="wrap section preview-catalog">${sectionTitle('UN CATÁLOGO PARA TI','Encuentra tu próximo <em>favorito.</em>','No te quedes solo con estas opciones: tenemos mucho más.',`<a class="button secondary" data-nav href="${urlBranch('/catalogo')}">Explorar catálogo ${icon('arrow',17)}</a>`)}${cards(products.slice(12,16))}</section>`};
const arranged=app.shop.sections.map(s=>s.id).filter(k=>selected[k]);return `<main>${storeHero()}<div class="wrap shop-intro-line"><div><span class="hello-dot"></span> Precios y existencias de <b>${esc(app.shop.branch.name)}</b></div><span>${app.shop.products.length} referencias en esta sucursal</span></div>${arranged.map(k=>selected[k]()).join('')}<section class="lf-scroll-story" aria-label="De la lista a tu cotización"><div class="wrap lf-story-sticky"><div class="lf-story-art" aria-hidden="true"><div class="lf-story-paper"><div class="lf-story-paper-top"></div><span></span><span></span><span></span><span></span><i></i></div><div class="lf-story-check lf-story-check-one">✓</div><div class="lf-story-check lf-story-check-two">✓</div><div class="lf-story-blob"></div></div><div class="lf-story-copy"><span class="eyebrow">COTIZACIONES ESCOLARES</span><h2>Una lista. <em>Tres maneras de elegir.</em></h2><div class="lf-story-steps"><p data-lf-step="0"><b>01 · Envíanos tu lista</b><span>Adjunta una foto o PDF de tu lista.</span></p><p data-lf-step="1"><b>02 · Elegimos opciones</b><span>Revisamos los productos disponibles en esta sucursal.</span></p><p data-lf-step="2"><b>03 · Recibe tu total</b><span>Un importe y un aviso si falta algún artículo.</span></p></div><a data-nav class="button primary" href="${urlBranch('/cotizar')}">Cotizar mi lista ${icon('arrow',17)}</a></div></div></section></main>`;}
function pageBanner(kicker,title,subtitle='',color='blue'){const motion=kicker==='CATÁLOGO'?'full':'simple';return `<section class="page-banner banner-${color}" data-banner-motion="${motion}"><div class="wrap"><div class="breadcrumbs"><a data-nav href="/">Inicio</a><span>›</span><a data-nav href="${urlBranch()}">${esc(app.shop.branch.name)}</a><span>›</span><span>${esc(kicker)}</span></div><div class="page-banner-body"><div><span class="eyebrow light">${kicker}</span><h1>${title}</h1><p>${subtitle}</p></div><div class="page-sparkle" aria-hidden="true">✦<i>✧</i></div></div></div></section>`;}
function catalogueProducts(){
 const key=[app.shop?.branch?.id,app.query,app.category,app.brand,app.stockOnly,app.order].join('\u001f');
 if(app.catalogCache?.shop===app.shop && app.catalogCache.key===key)return app.catalogCache.items;
 let xs=app.shop.products.filter(x=>x.price>0);
 const q=searchNormalized(app.query);
 if(q){
  const words=q.split(' ').filter(Boolean);
  xs=xs.map(p=>{
   let hay=catalogSearchTextCache.get(p);
   if(hay===undefined){hay=searchNormalized([p.name,p.brand,p.categoryId,p.subCategory,p.model,p.description,p.sku,p.searchAliases,p.usage].join(' '));catalogSearchTextCache.set(p,hay);}
   const matched=words.filter(x=>hay.includes(x)).length;
   return {...p,_score:hay.includes(q)?100+matched:matched===words.length?30+matched*3:matched>=2?matched:0};
  }).filter(p=>p._score>0);
 }
if(app.category!=='all')xs=xs.filter(p=>p.categoryId===app.category);if(app.brand!=='all')xs=xs.filter(p=>p.brand===app.brand);if(app.stockOnly)xs=xs.filter(p=>p.stock>0||p.isService);if(app.order==='low')xs.sort((a,b)=>a.price-b.price);else if(app.order==='high')xs.sort((a,b)=>b.price-a.price);else if(app.order==='az')xs.sort((a,b)=>a.name.localeCompare(b.name,'es'));else if(app.order==='new')xs.sort((a,b)=>Number(b.isNew)-Number(a.isNew));else if(q)xs.sort((a,b)=>b._score-a._score);app.catalogCache={key,shop:app.shop,items:xs};return xs;}
function suggestionsHtml(){const q=fold(app.query);if(q.length<2)return '';const picks=[];for(const p of app.shop.products){if(p.price>0&&fold(p.name+' '+p.brand).includes(q)){picks.push(p);if(picks.length>=5)break;}}return picks.length?`<div class="search-suggestions">${picks.map(p=>`<a data-nav href="${productUrl(p.id)}">${icon('search',14)} <span>${esc(p.name)}</span><small>${money(p.price)}</small></a>`).join('')}</div>`:'';}
function currentListingProducts(){
 const route=app.route?.page;
 if(route==='catalogo')return catalogueProducts();
 if(route==='ofertas'||route==='novedades')return campaignProducts(route);
 if(route==='especiales')return seasonalProducts();
 return [];
}
function listingMarkup(items,emptyHTML=''){
 const shown=Math.min(app.catalogShown,items.length);
 if(!items.length)return emptyHTML||`<div class="search-empty">${icon('search',38)}<h3>No encontramos productos con esos filtros.</h3><p>Prueba buscando otra marca, producto o presentación.</p><button class="button secondary" data-action="clear-filters">Ver todos los artículos</button></div>`;
 return `<div class="catalog-count" aria-live="polite"><span>Mostrando <b class="catalog-visible-count">${shown}</b> de <b>${items.length}</b> producto${items.length===1?'':'s'}</span><span>${esc(app.shop.branch.name)}</span></div><div class="products-grid" id="catalog-products-grid">${items.slice(0,shown).map(productCard).join('')}</div>${shown<items.length?`<div class="catalog-more-wrap" id="catalog-more-wrap"><button type="button" class="button secondary catalog-more-button" data-action="catalog-more">Ver ${Math.min(CATALOG_BATCH_SIZE,items.length-shown)} productos más ${icon('arrow',17)}</button><span class="catalog-more-hint">Los siguientes productos aparecerán debajo al pulsar el botón.</span></div>`:''}`;
}
function catalogueGrid(){return listingMarkup(catalogueProducts());}
function disconnectCatalogObserver(){catalogObserver?.disconnect();catalogObserver=null;}
function loadMoreCatalog(){
 if(!['catalogo','ofertas','novedades','especiales'].includes(app.route?.page))return;
 const grid=$('#catalog-products-grid'),more=$('#catalog-more-wrap');
 if(!grid||!more)return;
 const items=currentListingProducts();
 const end=Math.min(items.length,app.catalogShown+CATALOG_BATCH_SIZE);
 if(end<=app.catalogShown)return;
 const previous=app.catalogShown;
 grid.insertAdjacentHTML('beforeend',items.slice(previous,end).map(productCard).join(''));
 app.catalogShown=end;
 const count=$('.catalog-visible-count');if(count)count.textContent=String(end);
 if(end>=items.length)more.remove();
 else{const button=more.querySelector('.catalog-more-button');if(button)button.innerHTML=`Ver ${Math.min(CATALOG_BATCH_SIZE,items.length-end)} productos más ${icon('arrow',17)}`;}
 refreshProductReveal(grid);
}
// V29: la carga progresiva es manual. No se precargan productos al hacer scroll.
function mountCatalogObserver(){disconnectCatalogObserver();}
function catalogue(){const brands=[...new Set(app.shop.products.map(p=>p.brand))].sort((a,b)=>a.localeCompare(b,'es'));return `<main>${pageBanner('CATÁLOGO','Encuentra lo que <em>necesitas.</em>','Busca útiles, consulta precios y compara opciones en esta sucursal.','pink')}<div class="wrap catalogue-layout"><aside class="filter-sidebar"><div class="filter-title">${icon('filter',20)} <b>Filtrar productos</b><button data-action="clear-filters">Limpiar</button></div><div class="filter-block"><strong>Categorías</strong><div class="filter-options"><button class="filter-category ${app.category==='all'?'active':''}" data-action="cat" data-category="all">Todo el catálogo <span>${app.shop.products.length}</span></button>${app.shop.categories.map(c=>`<button class="filter-category ${app.category===c.id?'active':''}" data-action="cat" data-category="${esc(c.id)}">${esc(c.name)}<span>${app.shop.products.filter(p=>p.categoryId===c.id).length}</span></button>`).join('')}</div></div><div class="filter-block"><label for="brand-select"><strong>Marca</strong></label><select id="brand-select"><option value="all">Todas las marcas</option>${brands.map(b=>`<option ${b===app.brand?'selected':''} value="${esc(b)}">${esc(b)}</option>`).join('')}</select></div><div class="filter-block"><label class="check-filter"><input id="available-filter" type="checkbox" ${app.stockOnly?'checked':''}> Solo con stock</label></div><div class="filter-bottom-info">${icon('shield',20)} Precios y stock de la sucursal seleccionada.</div></aside><div class="catalog-main"><div class="catalogue-toolbar"><div class="search-zone"><label class="catalogue-search">${icon('search',21)} <input id="catalog-search" type="search" value="${esc(app.query)}" placeholder="Busca lápices, plumones x12, silicona..." autocomplete="off" aria-label="Buscar productos"></label><div id="catalog-suggestions">${suggestionsHtml()}</div></div><label class="order-wrap">Ordenar <select id="order-select"><option value="relevancia" ${app.order==='relevancia'?'selected':''}>Relevancia</option><option value="low" ${app.order==='low'?'selected':''}>Menor precio</option><option value="high" ${app.order==='high'?'selected':''}>Mayor precio</option><option value="new" ${app.order==='new'?'selected':''}>Novedades</option><option value="az" ${app.order==='az'?'selected':''}>A a Z</option></select></label></div><div class="mobile-category-chips"><button data-action="cat" data-category="all" class="${app.category==='all'?'active':''}">Todos</button>${app.shop.categories.map(c=>`<button data-action="cat" data-category="${esc(c.id)}" class="${app.category===c.id?'active':''}">${esc(c.name)}</button>`).join('')}</div><div class="mobile-filter-row"><label>Marca <select id="mobile-brand"><option value="all">Todas</option>${brands.map(b=>`<option value="${esc(b)}" ${app.brand===b?'selected':''}>${esc(b)}</option>`).join('')}</select></label><label class="check-filter"><input id="mobile-stock" type="checkbox" ${app.stockOnly?'checked':''}> Disponibles</label></div><div id="catalog-results">${catalogueGrid()}</div></div></div></main>`;}
function campaignProducts(which){let xs=app.shop.products.filter(p=>p.price>0);if(which==='ofertas')xs=xs.filter(p=>discount(p)>0);else xs=xs.filter(p=>p.isNew);return xs;}
function collection(which){const isOffers=which==='ofertas',products=campaignProducts(which);return `<main>${pageBanner(isOffers?'PROMOCIONES':'NOVEDADES',isOffers?'Tus favoritos con <em>algo extra.</em>':'Acaban de llegar <em>cosas bonitas.</em>',isOffers?'Descubre los productos con descuentos configurados para tu tienda.':'Un espacio para encontrar lo nuevo que va llegando.','pink')}<section class="wrap section">${sectionTitle(isOffers?'OFERTAS DE LA SUCURSAL':'LO MÁS RECIENTE',isOffers?'Descubre las <em>promociones.</em>':'Llegaron nuevas <em>ideas.</em>')}${listingMarkup(products,`<div class="search-empty"><h3>No hay productos en esta sección por ahora.</h3><p>Desde administración se pueden configurar descuentos y novedades en cualquier momento.</p><a data-nav class="button secondary" href="${urlBranch('/catalogo')}">Explorar catálogo</a></div>`)}</section></main>`;}
function compareTray(){if(!app.shop||!app.compareSelection?.length)return '';return `<aside class="compare-tray"><span>${icon('compare',18)} <b>${app.compareSelection.length} seleccionados</b> · máximo 4</span><div><button type="button" class="button secondary" data-action="clear-compare">Vaciar</button><a data-nav class="button primary" href="${urlBranch('/comparar')}">Ver comparación ${icon('arrow',16)}</a></div></aside>`;}
function updateCompareTray(){document.querySelector('.compare-tray')?.remove();if(app.shop&&app.compareSelection?.length)$('#app').insertAdjacentHTML('beforeend',compareTray());for(const btn of document.querySelectorAll('[data-action=compare-select]'))btn.classList.toggle('selected',app.compareSelection.includes(btn.dataset.id));}
function compareSelectedPage(){const xs=(app.compareSelection||[]).map(id=>app.shop.products.find(p=>p.id===id)).filter(Boolean);if(xs.length<2)return '';return `<main>${pageBanner('COMPARADOR','Compara lo que <em>elegiste.</em>','Productos seleccionados por ti, con precios exclusivamente de esta sucursal.','blue')}<section class="wrap section"><div class="compare-location-note">${icon('pin',17)} ${esc(app.shop.branch.name)} · ${xs.length} artículos</div><div class="compare-table-wrap"><table class="compare-table"><thead><tr><th>Características</th>${xs.map(p=>`<th>${picture(p,'mini-picture')}<strong>${esc(p.name)}</strong><small>${esc(p.brand)}</small></th>`).join('')}</tr></thead><tbody><tr><th>Precio</th>${xs.map(p=>`<td><strong class="compare-price">${money(p.price)}</strong></td>`).join('')}</tr><tr><th>Marca</th>${xs.map(p=>`<td>${esc(p.brand)}</td>`).join('')}</tr><tr><th>Presentación</th>${xs.map(p=>`<td>${esc(p.unitLabel)}${p.unitsPerPack>1?' x'+p.unitsPerPack:''}</td>`).join('')}</tr><tr><th>Disponibilidad</th>${xs.map(p=>`<td>${offerState(p)}</td>`).join('')}</tr><tr><th>Detalle</th>${xs.map(p=>`<td><a data-nav class="button secondary" href="${productUrl(p.id)}">Ver producto</a></td>`).join('')}</tr></tbody></table></div><p style="margin-top:18px">Si comparas artículos de formatos diferentes, ten en cuenta la cantidad y presentación de cada uno.</p></section></main>`;}
function comparePage(){const n=app.compareSelection?.length||0;if(n>=2)return compareSelectedPage();return `<main>${pageBanner('COMPARADOR','Compara lo que <em>tú eliges.</em>','Elige productos concretos desde el catálogo de esta misma sucursal.','blue')}<section class="wrap section compare-page"><div class="search-empty">${icon('compare',42)}<h3>${n===1?'Ya elegiste un producto':'Tu comparación comienza en el catálogo'}</h3><p>${n===1?'Selecciona al menos un producto más para ver las diferencias.':'Pulsa «Comparar» en los productos que te interesan. Puedes elegir de 2 a 4 artículos.'}</p><a data-nav class="button primary" href="${urlBranch('/catalogo')}">Elegir productos ${icon('arrow',17)}</a>${n===1?`<button type="button" data-action="clear-compare" class="button secondary">Limpiar selección</button>`:''}</div></section></main>`;}
function detailsPage(id){const p=app.shop.products.find(x=>x.id===id);if(!p)return `<main class="wrap section"><h1>No encontramos ese producto.</h1><a data-nav href="${urlBranch('/catalogo')}" class="button primary">Volver al catálogo</a></main>`;const similar=app.shop.products.filter(x=>x.id!==p.id&&x.comparisonGroup&&x.comparisonGroup===p.comparisonGroup&&x.stock>0).slice(0,4);const off=discount(p);return `<main><div class="wrap detail-breadcrumb"><a data-nav href="${urlBranch()}">Mi tienda</a><span>›</span><a data-nav href="${urlBranch('/categoria/'+p.categoryId)}">${esc(categoryName(p.categoryId))}</a><span>›</span><span>${esc(p.name)}</span></div><div class="wrap detail-grid"><div class="detail-gallery">${picture(p,'large-picture')}<div class="gallery-message">${icon('shield',16)} Imagen orientativa si aún no se cargó la fotografía oficial.</div></div><div class="detail-info"><span class="eyebrow">${esc(p.brand)} · ${esc(p.sku)}</span><h1>${esc(p.name)}</h1><div class="detail-subtitle">${esc(p.model||'Modelo por confirmar')} · ${esc(categoryName(p.categoryId))}</div><div class="detail-tags">${p.isNew?pill('Novedad','new'):''}${off?pill(`Descuento ${off}%`,'discount'):''}${pill('Precio por sucursal','')}</div><div class="detail-main-price">${money(p.price)} ${off?`<del>${money(p.compareAt)}</del>`:''}</div><div class="detail-stock-label">${offerState(p)} en <b>${esc(app.shop.branch.name)}</b></div><p class="detail-description">${esc(p.description||'Una opción para tus tareas, materiales y proyectos del día a día.')}</p><div class="detail-facts"><div><span>Presentación</span><b>${esc(p.unitLabel)}${p.unitsPerPack>1?' x'+p.unitsPerPack:''}</b></div><div><span>Contenido</span><b>${p.netContent?`${p.netContent} ${esc(p.netUnit)}`:'No especificado'}</b></div><div><span>Uso principal</span><b>${esc(p.usage||'Por definir')}</b></div></div><div class="detail-actions"><button class="button primary" data-action="add" data-id="${esc(p.id)}" ${p.stock<=0&&!p.isService?'disabled':''}>${icon('bag',19)} Añadir a mi lista</button><button type="button" data-action="compare-select" data-id="${esc(p.id)}" class="button secondary">${icon('compare',18)} Añadir a comparación</button></div></div></div><div class="wrap details-under"><section class="info-panel"><h2>Características y detalles</h2><div class="feature-row"><span>Marca</span><b>${esc(p.brand)}</b></div><div class="feature-row"><span>Modelo</span><b>${esc(p.model||'Sin especificar')}</b></div><div class="feature-row"><span>Presentación</span><b>${esc(p.unitLabel)}</b></div><div class="feature-row"><span>Características</span><b>${esc(p.features||'Pendiente de información específica del fabricante')}</b></div></section><section class="info-panel"><h2>Encuéntralo en tu sucursal</h2><p>Estás viendo el precio y el stock de <b>${esc(app.shop.branch.name)}</b>. Si buscas otras marcas o modelos, utiliza el comparador de esta misma tienda.</p><div class="detail-branch-info">${icon('pin',22)}<div><b>${esc(app.shop.branch.name)}</b><small>${esc(app.shop.branch.address||'Dirección por confirmar')}</small><small>${esc(app.shop.branch.hours||'Horario por confirmar')}</small></div></div><button type="button" data-action="compare-select" data-id="${esc(p.id)}" class="button secondary">${icon('compare',17)} Comparar este artículo</button></section></div>${similar.length?`<section class="wrap section">${sectionTitle('OPCIONES DE ESTA SUCURSAL','Quizá también te <em>interesen.</em>','Otras marcas y modelos disponibles aquí.')}${cards(similar)}</section>`:''}</main>`;}
function quotePage(){return `<main>${pageBanner('COTIZACIÓN ESCOLAR','Tu lista, <em>sin complicaciones.</em>','Un único precio final según tu preferencia. Si algo falta o requiere revisión, te lo indicaremos claramente.','purple')}<div class="wrap quote-main"><div class="quote-step-head"><span class="ai-chip">${icon('stars',16)} COTIZADOR ESCOLAR</span><h2>Sube tu lista y nosotros hacemos el cálculo</h2><p>Trabajamos con los precios publicados por <b>${esc(app.shop.branch.name)}</b>. Para evitar errores al escribir, esta sección recibe listas en <b>foto o PDF</b>.</p></div><div class="quote-layout"><form class="quote-form" id="quote-form"><div class="form-section"><div class="form-step-title"><span>01</span><div><h3>Elige cómo quieres tu cotización</h3><small>Seleccionaremos artículos compatibles según su precio y clasificación.</small></div></div><div class="quote-tiers">${[['economica','Económica','Ahorra al máximo','tag'],['equilibrada','Equilibrada','Un punto medio ideal','grid'],['calidad','Calidad prioritaria','Preferencia por productos mejor clasificados','shield']].map(([val,name,desc,sym])=>`<label class="quote-tier ${app.quoteTier===val?'selected':''}"><input type="radio" name="tier" value="${val}" ${app.quoteTier===val?'checked':''}><span class="tier-emoji">${icon(sym,18)}</span><b>${name}</b><small>${desc}</small><span class="radio-dot"></span></label>`).join('')}</div></div><div class="form-section"><div class="form-step-title"><span>02</span><div><h3>Adjunta tu lista</h3><small>Sube una foto clara o un archivo PDF. Formatos admitidos: JPG, PNG, WebP y PDF.</small></div></div><div class="quote-upload-panel"><div class="quote-upload-points"><div>${icon('check',16)} Foto tomada desde el celular</div><div>${icon('check',16)} Lista escolar escaneada</div><div>${icon('check',16)} Documento PDF</div></div><div class="file-upload-wrap"><input id="school-file" type="file" accept=".pdf,.png,.jpg,.jpeg,.webp,application/pdf,image/*"><label for="school-file" class="file-upload">${icon('upload',25)}<span><b>Subir foto o PDF</b><small id="file-name">JPG, PNG, WebP o PDF · máximo 8 MB</small></span>${icon('arrow',18)}</label></div><div class="ai-status-line" id="ai-status">${icon('file',16)} Preparando lector de archivos...</div></div></div><div class="form-submit"><button class="button primary wide" type="submit" id="quote-submit">${icon('stars',19)} Obtener cotización</button></div><p class="fineprint">Los importes se calculan con los precios publicados por la sucursal y se confirman al atenderte.</p></form><aside class="quote-output" id="quote-output"><div class="quote-output-top"><span class="eyebrow light">✦ TU RESULTADO</span>${icon('stars',32)}</div><div class="quote-result-placeholder"><div class="result-orb">${icon('file',42)}</div><h3>Tu cotización aparecerá aquí.</h3><p>Te daremos <b>un único precio</b>, sin mostrar los precios individuales. Si algún artículo no se puede reconocer, lo indicaremos debajo.</p></div><div class="output-points"><div>${icon('check',17)} Sin precios por artículo</div><div>${icon('check',17)} Tres niveles de cotización</div><div>${icon('check',17)} Avisos de artículos faltantes</div></div></aside></div></div><section class="wrap how-quote">${sectionTitle('PENSADO PARA TUS LISTAS','Así de <em>fácil.</em>')}<div class="how-quote-grid"><div><span>1</span><b>Sube tu archivo</b><p>Adjunta una foto clara o un PDF de tu lista.</p></div><div><span>2</span><b>Revisamos opciones</b><p>Comparamos productos disponibles en esta sucursal.</p></div><div><span>3</span><b>Recibe un único total</b><p>Y observa qué artículos necesitan revisión.</p></div></div></section></main>`;}
function quoteResultHTML(r){const issues=[...(r.unrecognized||[]).map(x=>({name:x,why:'Texto no entendible'})),...(r.missing||[]).map(x=>({name:x,why:'No encontrado o sin stock'}))];return `<div class="quote-output-top"><span class="eyebrow light">✦ RESULTADO DE TU LISTA</span>${icon('check',27)}</div><div class="quote-result-value"><div class="quote-receipt-code">Cotización N.º <strong>${esc(r.code||'')}</strong></div><span>${r.complete?'PRECIO TOTAL DE LA COTIZACIÓN':'SUBTOTAL DE LOS ARTÍCULOS ENCONTRADOS'}</span><strong>${money(r.total)}</strong><small>${r.includedCount} de ${r.totalCount} artículos incluidos · ${r.tier==='economica'?'Económica':r.tier==='equilibrada'?'Equilibrada':'Calidad prioritaria'}</small></div>${issues.length?`<div class="quote-alert">${icon('alert',22)} <div><strong>Tu lista necesita revisión.</strong><p>El importe no incluye los siguientes artículos:</p></div></div><div class="quote-issues">${issues.map(o=>`<div><b>${esc(o.name)}</b><small>${esc(o.why)}</small></div>`).join('')}</div>`:`<div class="quote-complete">${icon('check',18)} Todos los artículos de la lista fueron incluidos.</div>`}<p class="result-notice">Precios referenciales, sujetos a confirmación y disponibilidad. No se reserva mercadería.</p><button class="button light wide" data-action="quote-reset" type="button">Cotizar otra lista ${icon('arrow',17)}</button>`;}
function services(){return `<main>${pageBanner('SERVICIOS','Más que productos, <em>soluciones.</em>','Para el colegio, la oficina, tus ideas y tus proyectos.','blue')}<section class="wrap section">${sectionTitle('TAMBIÉN PODEMOS AYUDARTE','Todo lo que necesitas <em>en un solo lugar.</em>')}<div class="services-grid">${[['printer','Copias e impresiones','Apoyo para tareas, apuntes y documentos.'],['book','Útiles escolares','Cuadernos, lápices, colores y todos esos pequeños imprescindibles.'],['palette','Arte y manualidades','Materiales para darle forma a tus ideas.'],['file','Anillados y enmicados','Acabados prácticos para documentos y proyectos.'],['gift','Campañas de temporada','Detalles para fechas especiales y celebraciones.'],['stars','Cotizaciones escolares','Una sola cifra para tu lista, por modalidad.']].map(([ic,title,sub])=>`<article class="service-card">${icon(ic,27)}<h3>${title}</h3><p>${sub}</p></article>`).join('')}</div></section>${(()=>{const services=app.shop.products.filter(p=>p.isService&&p.price>0);return services.length?`<section class="wrap section"><div class="section-header"><div><span class="eyebrow">TARIFAS DE ESTA SUCURSAL</span><h2>Servicios disponibles</h2><p>Precios actualizados desde el administrador.</p></div></div><div class="products-grid">${services.map(productCard).join('')}</div></section>`:'';})()}</main>`;}
function appPage(){if(!app.shop)return gateway();switch(app.route.page){case 'catalogo':case 'categoria':return catalogue();case 'comparar':return comparePage();case 'cotizar':return quotePage();case 'producto':return detailsPage(app.route.id);case 'ofertas':return collection('ofertas');case 'novedades':return collection('novedades');case 'servicios':return services();case 'impresiones':return printQuotePage();case 'campanas':return seasonArchivePage();case 'especiales':return seasonalPage();default:return storefront();}}
function breadcrumbTitle(){return app.route?.page==='producto'?app.shop?.products.find(p=>p.id===app.route.id)?.name:({catalogo:'Catálogo',comparar:'Comparador',cotizar:'Cotizador escolar',ofertas:'Promociones',novedades:'Novedades',servicios:'Servicios',impresiones:'Copias e impresiones',campanas:'Campañas',especiales:'Especiales'})[app.route?.page]||app.shop?.branch?.name||'Inicio';}
function render(){disconnectCatalogObserver();clearTimeout(catalogSearchTimer);applyBrandTheme();document.body.classList.toggle('gateway-focus-route',!app.shop);$('#app').innerHTML=header()+appPage()+compareTray()+footer()+whatsappFloat()+'<div id="overlay-root"></div><div id="toast-root" aria-live="polite"></div>';document.title=`${breadcrumbTitle()} | ${currentBranding().name}`;reveal();for(const [name,run] of [['movimiento',mountMotion],['entradas',initHomeReveal],['productos',()=>initProductReveal()],['agua de portada',mountGatewayFocus],['flotantes',mountFloatingBackground],['detalles',mountExtraReveals],['banners de sucursal',mountBranchHeroCarousel],['banner del catálogo',mountBannerMotion]]){try{run();}catch(error){if(name==='productos')document.documentElement.classList.remove('lfpr-enabled');console.error('[La Favorita: '+name+']',error);}}mountCatalogObserver();refreshOfferClocks();}
function parseRoute(path){const found=path.match(/^\/tienda\/([^/]+)(?:\/(.*))?$/);if(!found)return {page:'gateway',branch:null};const rem=found[2]||'';const [page,id]=rem.split('/');return {page:page||'home',id:decodeURIComponent(id||''),branch:decodeURIComponent(found[1])};}
async function navigate(path,{replace=false,scroll=true}={}){try{const target=new URL(path,location.origin);if(target.origin!==location.origin){location.href=path;return;}const route=parseRoute(target.pathname);app.catalogShown=CATALOG_BATCH_SIZE;app.catalogCache=null;if(route.page==='categoria'){app.category=route.id;route.page='catalogo';}else if(route.page!=='catalogo'){app.category='all';app.brand='all';app.query='';app.order='relevancia';app.stockOnly=false;}if(route.page==='comparar'){app.compareProduct=target.searchParams.get('producto')||'';app.compareGroup=target.searchParams.get('grupo')||'';}if(route.page==='catalogo'&&target.searchParams.get('q'))app.query=target.searchParams.get('q');if(!app.bootstrap)app.bootstrap=await api('/api/bootstrap');if(route.branch){if(!app.shop||app.shop.branch.id!==route.branch){app.shop=await api(`/api/store/${encodeURIComponent(route.branch)}`);app.branchId=route.branch;readCart();readCompare();}else if(Date.now()-app.loadedAt>15000){app.shop=await api(`/api/store/${encodeURIComponent(route.branch)}`);}}else{app.shop=null;app.branchId=null;app.cart=[];}app.route=route;app.menu=false;app.cartOpen=false;app.loadedAt=Date.now();if(location.pathname+location.search!==target.pathname+target.search){history[replace?'replaceState':'pushState'](null,'',target.pathname+target.search);}if(document.startViewTransition && !matchMedia('(prefers-reduced-motion: reduce)').matches){document.startViewTransition(()=>render());}else render();if(route.page==='impresiones'){loadPrintRates();}if(route.page==='cotizar')loadAIStatus();if(scroll)window.scrollTo({top:0,behavior:'instant'});}
catch(e){$('#app').innerHTML=`<div class="error-screen"><h1>No pudimos abrir la tienda</h1><p>${esc(e.message)}</p><a href="/" class="button primary">Volver al inicio</a></div>`;console.error(e);}}
async function loadAIStatus(){try{app.aiStatus=await api('/api/ai/status');const el=$('#ai-status');if(el)el.innerHTML=app.aiStatus.configured?`${icon('check',17)} Lectura automática de fotos y PDF habilitada.`:`${icon('shield',17)} La lectura automática de archivos no está disponible en este momento.`;}catch{const el=$('#ai-status');if(el)el.innerHTML=`${icon('alert',17)} No se pudo comprobar el lector de archivos.`;}}
async function requestQuote(){const file=$('#school-file')?.files[0];if(!file)throw Error('Adjunta una foto o PDF de la lista.');if(file.size>8*1024*1024)throw Error('El archivo supera los 8 MB.');if(!app.aiStatus?.configured)throw Error('La lectura automática de archivos no está disponible en este momento.');const payload={branchId:app.branchId,tier:app.quoteTier};const mimeType=file.type||({'pdf':'application/pdf','png':'image/png','jpg':'image/jpeg','jpeg':'image/jpeg','webp':'image/webp'}[file.name.split('.').pop().toLowerCase()]);if(!['application/pdf','image/png','image/jpeg','image/webp'].includes(mimeType))throw Error('Formato no permitido.');const data=await new Promise((ok,fail)=>{const reader=new FileReader();reader.onload=()=>ok(reader.result);reader.onerror=fail;reader.readAsDataURL(file);});payload.file={filename:file.name,mimeType,base64:String(data).split(',')[1]};return api('/api/school-quote',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});}
async function submitQuote(){const el=$('#quote-output'),button=$('#quote-submit');if(button)button.disabled=true;el.innerHTML=`<div class="loading-quote"><div class="spinner"></div><h3>Revisando tu lista...</h3><p>Comprobando productos, opciones y precios de esta sucursal.</p></div>`;try{const result=await requestQuote();el.innerHTML=quoteResultHTML(result);app.quoteResult=result;el.scrollIntoView({behavior:'smooth',block:'nearest'});}catch(e){el.innerHTML=`<div class="quote-result-placeholder"><div class="result-orb">${icon('alert',37)}</div><h3>No se pudo calcular todavía</h3><p>${esc(e.message)}</p></div>`;}finally{if(button)button.disabled=false;}}
function addCart(id){const product=app.shop?.products.find(p=>p.id===id);if(!product||(product.stock<=0&&!product.isService))return toast('Este artículo no está disponible.');let item=app.cart.find(x=>x.id===id);if(!item){item={id,qty:0};app.cart.push(item);}item.qty=Math.min(product.isService?99:product.stock,item.qty+1);writeCart();const count=$('.cart-count');if(count)count.textContent=cartCount();toast('¡Agregado a tu lista!');}
function cartContents(){let total=0;const items=app.cart.map(x=>{const p=app.shop?.products.find(p=>p.id===x.id);if(!p)return '';total+=p.price*x.qty;return `<div class="cart-item">${picture(p,'cart-product-image')}<div><b>${esc(p.name)}</b><small>${money(p.price)} · ${esc(p.brand)}</small><div class="qty-edit"><button data-action="qty" data-id="${esc(p.id)}" data-step="-1">−</button><strong>${x.qty}</strong><button data-action="qty" data-id="${esc(p.id)}" data-step="1">+</button></div></div><button data-action="remove" data-id="${esc(p.id)}" class="cart-remove">${icon('close',17)}</button></div>`;}).join('');return {items,total};}
function openCart(){if(!app.shop)return;app.cartOpen=true;const {items,total}=cartContents();$('#overlay-root').innerHTML=`<div class="drawer-backdrop" data-action="close-cart"><aside class="cart-drawer" role="dialog" aria-modal="true" aria-label="Mi lista de productos"><header class="drawer-heading"><div><span class="eyebrow">MI LISTA DE COMPRA</span><h2>Mis favoritos <em>para llevar.</em></h2></div><button class="icon-button" data-action="close-cart" aria-label="Cerrar lista">${icon('close',22)}</button></header><div class="drawer-items">${items||`<div class="cart-empty">${icon('bag',44)}<h3>Tu lista está esperando.</h3><p>Agrega productos para preparar una consulta de tu sucursal.</p></div>`}</div><div class="cart-drawer-bottom"><div><span>Total referencial</span><b>${money(total)}</b></div><button class="button primary wide" data-action="copy-cart" ${!app.cart.length?'disabled':''}>${icon('copy',17)} Copiar lista</button><small>No procesamos pagos ni reservas desde esta sección.</small></div></aside></div>`;document.body.classList.add('lock-scroll');}
function closeCart(){app.cartOpen=false;$('#overlay-root').innerHTML='';document.body.classList.remove('lock-scroll');}
function changeQty(id,step){const it=app.cart.find(i=>i.id===id),p=app.shop?.products.find(p=>p.id===id);if(!it||!p)return;it.qty=Math.max(0,Math.min(p.isService?99:p.stock,it.qty+step));if(it.qty===0)app.cart=app.cart.filter(x=>x.id!==id);writeCart();const badge=$('.cart-count');if(badge)badge.textContent=cartCount();openCart();}
async function copyCart(){const {total}=cartContents();const lines=app.cart.map(x=>{const p=app.shop.products.find(p=>p.id===x.id);return p?`${x.qty} × ${p.name} (${p.brand}) — ${money(p.price*x.qty)}`:'';}).filter(Boolean);const s=`LA FAVORITA — Consulta de productos\nSucursal: ${app.shop.branch.name}\n\n${lines.join('\n')}\n\nTotal referencial: ${money(total)}\nPrecios a confirmar en tienda.`;try{await navigator.clipboard.writeText(s);toast('¡Lista copiada! Ya puedes compartirla.');}catch{const ta=document.createElement('textarea');ta.value=s;document.body.append(ta);ta.select();document.execCommand('copy');ta.remove();toast('Lista copiada.');}}
function toast(message){let t=$('#toast-root');if(!t)return;t.innerHTML=`<div class="toast-message">${icon('check',18)} ${esc(message)}</div>`;clearTimeout(app.toastTimer);app.toastTimer=setTimeout(()=>{if(t)t.innerHTML='';},3400);}
let stopBasicReveal=()=>{};
function reveal(){
  stopBasicReveal();stopBasicReveal=()=>{};
  const els=$$('[data-reveal]').filter(el=>!el.closest('[data-lf-home-reveal],.lfpr-slot'));
  if(!('IntersectionObserver' in window)||matchMedia('(prefers-reduced-motion: reduce)').matches){els.forEach(el=>el.classList.add('visible'));return;}
  const io=new IntersectionObserver(entries=>{
    for(const entry of entries){
      if(entry.isIntersecting)entry.target.classList.add('visible');
      else entry.target.classList.remove('visible');
    }
  },{rootMargin:'50px 0px 50px 0px',threshold:0});
  els.forEach(el=>io.observe(el));
  stopBasicReveal=()=>io.disconnect();
}
function refreshCatalog(){const result=$('#catalog-results');if(result){disconnectCatalogObserver();app.catalogShown=CATALOG_BATCH_SIZE;app.catalogCache=null;result.innerHTML=catalogueGrid();reveal();mountCatalogObserver();refreshProductReveal(result);}}
document.addEventListener('click',async event=>{
 const a=event.target.closest('a[data-nav]');if(a && !event.ctrlKey&&!event.metaKey&&!event.shiftKey&&event.button===0){event.preventDefault();await navigate(a.href);return;}
 const btn=event.target.closest('[data-action]');if(!btn)return;const action=btn.dataset.action;
 if(action==='toggle-menu'){app.menu=!app.menu;render();return;}
 if(action==='switch-branch'){const menu=$('#branch-switch-menu');const trigger=$('#branch-switch-btn');if(!menu||!trigger)return;const wasHidden=menu.hidden;menu.hidden=!wasHidden;trigger.setAttribute('aria-expanded',String(wasHidden));if(wasHidden)trigger.focus({preventScroll:true});return;}
 if(action==='catalog-more'){loadMoreCatalog();return;}
 if(action==='compare-select'){const id=btn.dataset.id;if(app.compareSelection.includes(id))app.compareSelection=app.compareSelection.filter(x=>x!==id);else if(app.compareSelection.length<4)app.compareSelection.push(id);else return toast('Puedes comparar hasta cuatro productos.');writeCompare();if(app.route?.page==='comparar')render();else updateCompareTray();return;}
 if(action==='clear-compare'){app.compareSelection=[];writeCompare();if(app.route?.page==='comparar')render();else updateCompareTray();return;}
 if(action==='add'){addCart(btn.dataset.id);return;}
 if(action==='cart'){openCart();return;}
 if(action==='close-cart'){if(btn===event.target||btn.closest('.drawer-heading'))closeCart();return;}
 if(action==='remove'){app.cart=app.cart.filter(x=>x.id!==btn.dataset.id);writeCart();openCart();return;}
 if(action==='qty'){changeQty(btn.dataset.id,Number(btn.dataset.step));return;}
 if(action==='copy-cart'){await copyCart();return;}
 if(action==='cat'){app.category=btn.dataset.category;$$('[data-action="cat"]').forEach(x=>x.classList.toggle('active',x.dataset.category===app.category));refreshCatalog();return;}
 if(action==='clear-filters'){app.query='';app.category='all';app.brand='all';app.order='relevancia';app.stockOnly=false;app.catalogShown=CATALOG_BATCH_SIZE;app.catalogCache=null;render();return;}
 if(action==='quote-reset'){app.quoteResult=null;await navigate(urlBranch('/cotizar'));return;}
});
document.addEventListener('input',e=>{if(e.target.name==='colorPercent'&&e.target.closest('#print-quote-form')){syncPrintColorMode();return;}if(e.target.id==='catalog-search'){app.query=e.target.value;clearTimeout(catalogSearchTimer);catalogSearchTimer=setTimeout(()=>{if(app.route?.page!=='catalogo')return;refreshCatalog();const el=$('#catalog-suggestions');if(el)el.innerHTML=suggestionsHtml();},180);}});
async function estimateImageColor(file){if(!file||!/^image\/(png|jpeg|webp)$/.test(file.type)||file.size>8*1024*1024)throw Error('Selecciona una imagen JPG, PNG o WebP de máximo 8 MB.');const image=new Image();const url=URL.createObjectURL(file);try{await new Promise((ok,fail)=>{image.onload=ok;image.onerror=fail;image.src=url;});const c=document.createElement('canvas');c.width=96;c.height=96;const ctx=c.getContext('2d',{willReadFrequently:true});ctx.fillStyle='white';ctx.fillRect(0,0,96,96);ctx.drawImage(image,0,0,96,96);const pixels=ctx.getImageData(0,0,96,96).data;let color=0,total=0;for(let i=0;i<pixels.length;i+=4){const r=pixels[i],g=pixels[i+1],b=pixels[i+2],hi=Math.max(r,g,b),lo=Math.min(r,g,b);if(hi<245||lo<238)total++;if(hi-lo>27&&hi<252&&lo<240)color++;}const coverage=color/(96*96);return {coverage,category:coverage<.14?'low':coverage<.40?'medium':'high'};}finally{URL.revokeObjectURL(url);}}
document.addEventListener('change',async e=>{if(e.target.id==='print-service-kind'){syncPrintService();return;}if(e.target.id==='print-color-mode'){syncPrintColorMode();return;}if(e.target.id==='print-color-reference'){const file=e.target.files?.[0];if(!file)return;try{const out=await estimateImageColor(file);const select=$('#print-quote-form [name=coverage]');if(select)select.value=out.category;const target=$('#print-color-analysis');if(target)target.textContent=`Estimación visual: ${(out.coverage*100).toFixed(1)}% de píxeles de color · ${out.category==='low'?'poco':out.category==='medium'?'moderado':'mucho'} color. Verifica el resultado antes de imprimir.`;}catch(error){const target=$('#print-color-analysis');if(target)target.textContent=error.message;}return;}if(e.target.id==='brand-select'||e.target.id==='mobile-brand'){app.brand=e.target.value;refreshCatalog();}if(e.target.id==='available-filter'||e.target.id==='mobile-stock'){app.stockOnly=e.target.checked;refreshCatalog();}if(e.target.id==='order-select'){app.order=e.target.value;refreshCatalog();}if(e.target.id==='compare-group'){app.compareProduct='';app.compareGroup=e.target.value;render();}if(e.target.name==='tier'){app.quoteTier=e.target.value;$$('.quote-tier').forEach(x=>x.classList.toggle('selected',x.querySelector('input').checked));}if(e.target.id==='school-file'){const label=$('#file-name');if(label)label.textContent=e.target.files[0]?.name||'JPG, PNG, WebP o PDF · máximo 8 MB';}});
document.addEventListener('submit',async e=>{if(e.target.id==='quote-form'){e.preventDefault();submitQuote();return;}if(e.target.id==='print-quote-form'){e.preventDefault();const form=e.target,result=$('#print-result');const data=Object.fromEntries(new FormData(form));data.branchId=app.branchId;data.duplex=form.querySelector('[name=duplex]').checked;result.textContent='Calculando…';try{const out=await api('/api/print-quote',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});result.innerHTML=`<strong>${money(out.total)}</strong><span>${out.kind==='scan'?`${out.pages} páginas digitalizadas · ${out.scanFormat==='jpg'?'JPG':'PDF'}`:`${out.faces} caras · ${out.sheets} hojas físicas`}</span>${out.color==='mixed'?`<small>${out.colorPages} pág. color · ${out.bwPages} pág. B/N · promedio ${money(out.unit)} por cara antes de descuentos</small>`:''}<small>${esc(out.note||'Importe estimado para esta sucursal.')}</small>`;}catch(error){result.textContent=error.message;}return;}});
document.addEventListener('error',e=>{if(e.target.tagName==='IMG'&&e.target.dataset.fallback&&e.target.src!==new URL(e.target.dataset.fallback,location.href).href){e.target.src=e.target.dataset.fallback;}},true);
document.addEventListener('keydown',e=>{if(e.key==='Escape'){if(app.cartOpen)closeCart();const open=!$('#branch-switch-menu')?.hidden;if(open){closeBranchMenu();$('#branch-switch-btn')?.focus();}}});
window.addEventListener('scroll',()=>{const b=document.documentElement;const d=Math.max(1,b.scrollHeight-b.clientHeight);document.documentElement.style.setProperty('--page-progress',Math.min(100,Math.max(0,window.scrollY/d*100))+'%');},{passive:true});
let branchRefreshPending=false;
window.addEventListener('lf10:branchesChanged',async()=>{
 if(branchRefreshPending||app.route?.page!=='gateway')return;
 branchRefreshPending=true;
 try{const fresh=await api('/api/bootstrap');if(!app.bootstrap||fresh.version!==app.bootstrap.version){app.bootstrap=fresh;render();}}
 catch(error){console.debug('No se pudieron recargar las sucursales',error);}
 finally{branchRefreshPending=false;}
});
window.addEventListener('popstate',()=>navigate(location.pathname+location.search,{replace:true,scroll:false}));
window.addEventListener('mousemove',e=>{if(matchMedia('(prefers-reduced-motion: reduce)').matches)return;const visual=$('.hero-visual');if(!visual)return;const rect=visual.getBoundingClientRect();const x=(e.clientX-(rect.left+rect.width/2))/rect.width;const y=(e.clientY-(rect.top+rect.height/2))/rect.height;visual.style.setProperty('--mouse-x',`${(x*13).toFixed(2)}px`);visual.style.setProperty('--mouse-y',`${(y*13).toFixed(2)}px`);},{passive:true});
await navigate(location.pathname+location.search,{replace:true});
setInterval(async()=>{if(!app.bootstrap||app.cartOpen)return;try{const current=await api('/api/version');if(current.version!==app.bootstrap.version){app.bootstrap=await api('/api/bootstrap');app.shop=null;await navigate(location.pathname+location.search,{replace:true,scroll:false});}}catch{}},30000);

function refreshOfferClocks(){for(const el of document.querySelectorAll('[data-deadline]')){const left=Date.parse(el.dataset.deadline)-Date.now();if(!Number.isFinite(left)){el.textContent='';continue;}if(left<=0){el.textContent='Oferta finalizada';continue;}const d=Math.floor(left/86400000),h=Math.floor(left%86400000/3600000),m=Math.floor(left%3600000/60000);el.textContent=`Termina en ${d?d+'d ':''}${String(h).padStart(2,'0')}h ${String(m).padStart(2,'0')}m`;}}
setInterval(refreshOfferClocks,15000);

setInterval(async()=>{if(!app.shop||document.hidden||app.cartOpen)return;try{const response=await api(`/api/commerce/active/${encodeURIComponent(app.branchId)}`);const next=(response.items||[]).map(o=>o.productId+':'+o.salePrice).sort().join('|');const current=app.shop.products.filter(p=>p.timeLimitedUntil).map(p=>p.id+':'+p.price).sort().join('|');if(next!==current){app.shop=await api(`/api/store/${encodeURIComponent(app.branchId)}`);app.loadedAt=Date.now();render();}}catch{}},45000);
